def minimum_cost_to_merge_fruits(fruit_counts: List[int]) -> int:
    # Build min heap using the fruit counts
    heap = []
    for i in range(len(fruit_counts)):
        heapq.heappush(heap, (fruit_counts[i], i))

    # Merge heaps in a greedy manner
    merged_heap = []
    while len(heap) > 1:
        (weight1, i1), (weight2, i2) = heapq.heappop(heap), heapq.heappop(heap)
        merged_heap.append(max(weight1, weight2))
        if len(heap) > 0:
            heapq.heappush(heap, (heapq.heappop(heap)[0] - max(weight1, weight2), i1))

    return sum(merged_heap)

def min_groups(w, n, prices):
    """Determines the minimum number of groups needed to distribute souvenirs with a constraint on the group's total price."""
    num_groups = 0
    current_group_sum = 0
    for i in range(n):
        if current_group_sum + prices[i] <= w:
            current_group_sum += prices[i]
        else:
            num_groups += 1
            current_group_sum = prices[i]
    if current_group_sum > 0:
        num_groups += 1
    return num_groups

def min_groups(w, n, prices):
    prices.sort()
    groups = 0
    group_sum = 0
    while n > 0:
        group_sum += prices[n-1]
        if group_sum > w:
            groups += 1
            group_sum = 0
        n -= 1
    if group_sum > 0:
        groups += 1
    return groups

def total_smoked_cigarettes(n, k):
    total = n
    while total >= k:
        total += total // k
